class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] suffixCounts = new int[12];

        for (String word : words) {
            suffixCounts[frequency(word)]++;
        }

        for (int i = 10; i >= 1; i--) {
            suffixCounts[i] += suffixCounts[i + 1];
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            answer[i] = suffixCounts[frequency(queries[i]) + 1];
        }

        return answer;
    }

    private int frequency(String s) {
        char smallest = '{';
        int count = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < smallest) {
                smallest = c;
                count = 1;
            } else if (c == smallest) {
                count++;
            }
        }

        return count;
    }
}

